from lib import *
def sq():
    b=''
    for n,x in ((1,20),(2,90),(3,180),(4,300)):
        for i in range(n):
            for j in range(n): b+=f'<circle cx="{x+j*22}" cy="{60+i*22}" r="8" fill="#e67e22" stroke="#333"/>'
        b+=f'<text x="{x}" y="170">{n*n}</text>'
    b+='<text x="20" y="25" font-weight="bold">Square numbers as dot squares: 1, 4, 9, 16</text>'
    return b
svgfile('c6-maths-square-dots.svg',460,190,sq())
chapter(6,'maths','patterns-in-mathematics','Patterns in Mathematics',
 ('Dots on the floor','Meena put 1 pebble, then 3 more, then 5 more to build a bigger and bigger square on the ground. Every time the square grew, the total was 1, 4, 9, 16. She did not plan it. The pattern simply appeared. Let us find out why.'),
 [('What is mathematics?',['Mathematics is largely the search for patterns, and for the reasons why those patterns exist.','Patterns are everywhere: in cooking, in shopping, in the way a ball flies and in the motion of the sun, moon and stars.','Finding why a pattern happens matters as much as finding the pattern, because the reason can be used again in new places.','For example, patterns in the motion of planets led people to the idea of gravity, and then to satellites and rockets.']),
  ('Number sequences',['A list of numbers that follows a rule is called a number sequence.','The study of patterns in whole numbers is called number theory.','Some famous sequences are: all 1s, counting numbers 1, 2, 3, odd numbers 1, 3, 5, even numbers 2, 4, 6.','Triangular numbers are 1, 3, 6, 10, 15. Each time we add one more than we added before.','Square numbers are 1, 4, 9, 16, 25. Cube numbers are 1, 8, 27, 64, 125.','The Virahanka numbers are 1, 2, 3, 5, 8, 13. Each number is the sum of the two numbers before it.','Powers of 2 are 1, 2, 4, 8, 16: each number is double the one before. Powers of 3 triple each time.']),
  ('Pictures of sequences',['We can draw a sequence. Triangular numbers are dots arranged in a triangle, square numbers are dots in a square grid, and cubes are blocks in a cube.','That is why they have these names. The number 36 is both a triangle and a square of dots.','Hexagonal numbers 1, 7, 19, 37 are dots arranged in rings around a centre dot like a honeycomb.']),
  ('Sequences are related',['Sequences are connected in surprising ways. Add the odd numbers one after another: 1, then 1 plus 3 is 4, then 1 plus 3 plus 5 is 9.','The totals are the square numbers. Why? A picture explains it: a square grid of dots splits into an L shape of 1 dot, then an L of 3, then 5, then 7.','Each L shape is the next odd number, and the square can be as big as we like, so the pattern goes on forever.','So the sum of the first 10 odd numbers is 10 times 10, which is 100.','Another pattern: 1, 1 plus 2 plus 1, 1 plus 2 plus 3 plus 2 plus 1. Adding up to a number and back down again also gives squares: 4, 9, 16.','Adding two neighbouring triangular numbers, like 1 plus 3 or 3 plus 6, also gives a square number.']),
  ('Patterns in shapes',['Mathematics also studies patterns of shapes, which is called geometry.','A shape sequence grows by a rule, such as adding one more square or one more line each step.','To describe it, we count what is added at each step and say the rule in our own words.'])],
 [('Add the first 5 odd numbers.',[('1 plus 3 plus 5 plus 7 plus 9 equals 25.','Add them one after another.'),('That is 5 times 5.','The sum of the first n odd numbers is n squared.')]),
  ('What are the next three numbers in 1, 3, 6, 10, 15?',[('The gaps are 2, 3, 4, 5, so the next gaps are 6, 7, 8.','Triangular numbers add one more each time.'),('21, 28, 36.','15 plus 6, 21 plus 7, 28 plus 8.')])],
 ('Explain to a friend why 1 + 3 + 5 + 7 always makes a square number.',['Square numbers are dots in a square grid.','A square splits into L shapes of 1, 3, 5, 7 dots.','The picture works for a square of any size.'],['Thinking a pattern is true only because a few examples worked.','Not asking why the pattern happens.']),
 ['Mathematics is the search for patterns and the reasons behind them.','Number sequences follow rules: odd, even, triangular, square, cube, powers of 2, Virahanka.','Pictures help us see and explain patterns.','The sum of the first n odd numbers is n squared.','Shape patterns also grow by rules.'],
 [mcq('p1-1',1,'What is the next number in 1, 4, 9, 16, 25, ...?','36',[('30','Add 5 gives 30, but the gaps grow 3, 5, 7, 9, so the next gap is 11.'),('35','The gap after 25 is 11, not 10.')],'These are squares: 6 times 6 is 36.'),
  mcq('p1-2',1,'Which sequence is 1, 3, 6, 10, 15?','Triangular numbers',[('Square numbers','Squares are 1, 4, 9, 16.'),('Odd numbers','Odd numbers are 1, 3, 5, 7.')],'Each number is the count of dots in a triangle.'),
  mcq('p1-3',1,'1 + 3 + 5 + 7 equals',' 16'.strip(),[('15','Check again: 1 plus 3 is 4, plus 5 is 9, plus 7 is 16.'),('12','Add every number carefully.')],'Four odd numbers add up to 4 times 4.'),
  tf('p1-4',1,'Doubling each time gives the powers of 2: 1, 2, 4, 8, 16.',True,'Each number is twice the one before.'),
  num('p1-5',2,'What is the sum of the first 10 odd numbers?',100,'The sum of the first n odd numbers is n times n, and 10 times 10 is 100.',[(55,'55 is the sum of 1 to 10, not of odd numbers.')]),
  mcq('p1-6',2,'Which number is both a triangular number and a square number?','36',[('30','30 is not a perfect square.'),('25','25 is a square but not triangular.')],'36 dots form a triangle and a square.'),
  mcq('p1-7',2,'Why is the pattern 1 + 3 + 5 + ... = square true forever?','A square grid can be split into L shapes of odd numbers for any size',[('We checked 100 examples','Checking examples is not an explanation.'),('Because the book says so','Mathematics gives reasons, not just rules.')],'The picture works for squares of every size.'),
  num('p1-8',2,'What is the next number in the Virahanka sequence 1, 2, 3, 5, 8, 13, ...?',21,'Add the last two: 8 plus 13 equals 21.',[(18,'Add the previous two numbers, not 5.')]),
  mcq('p1-9',3,'The sum of two neighbouring triangular numbers, like 3 + 6, is',' a square number'.strip(),[('a cube number','9 is a square, not a cube.'),('an odd number only','9 is odd, but it is specifically a square.')],'3 plus 6 is 9, 6 plus 10 is 16.'),
  num('p1-10',3,'What is 1 + 2 + 3 + 4 + 3 + 2 + 1?',16,'Adding up and down to 4 gives 4 times 4.',[(10,'That is only the up part 1 plus 2 plus 3 plus 4.')])],
 svgs=[('c6-maths-square-dots','Dots arranged in squares of side 1, 2, 3 and 4','Square numbers: 1, 4, 9, 16')],keep=['pattern','sequence','triangular','square'])
